"""Authored, locale-complete launch content for the Help Center.

This module deliberately contains data only.  Management-command safety and
database reconciliation live in ``seed_launch_help``.
"""

from dataclasses import dataclass

from support.taxonomy import REFUND_CATEGORY_SLUG


@dataclass(frozen=True)
class LaunchCategory:
    slug: str
    name: str
    name_fa: str
    description: str
    description_fa: str
    icon: str


@dataclass(frozen=True)
class LaunchHelpArticle:
    slug: str
    category_slug: str
    title: str
    title_fa: str
    summary: str
    summary_fa: str
    content: str
    content_fa: str
    is_featured: bool = False
    is_published: bool = True


