    LaunchCategory("orders-delivery", "Orders & Delivery", "سفارش‌ها و ارسال", "Guidance for placing, tracking, and managing orders.", "راهنمای ثبت، پیگیری و مدیریت سفارش‌ها.", "package"),
    LaunchCategory("payments", "Payments", "پرداخت‌ها", "Information about available payment actions and payment status.", "اطلاعات روش‌های پرداخت و وضعیت پرداخت سفارش.", "credit-card"),
